import sys; sys.path[:0]=['/workspace/project','/opt/emicro-deps']
import syntax
from compiler import automata, compiler
text='match() drop;(not(match(A,C,A)) or match(A,B,A)) allow;(contains() and (match(C) or endswith(C))) allow;match(B) drop;'
rules,a,s=syntax.parse(text)
names=['A','B','C']; index={n:i for i,n in enumerate(names)}
fast=automata.compile_rules(rules,[1,2,3],index)
ref=compiler.compile_rules(rules,[1,2,3],index)
print(fast); print(ref)
# oracle
def evaluate(predicate, word):
    kind=predicate[0]
    if kind=='not': return not evaluate(predicate[1],word)
    if kind=='and': return evaluate(predicate[1],word) and evaluate(predicate[2],word)
    if kind=='or': return evaluate(predicate[1],word) or evaluate(predicate[2],word)
    path=[index[n] for n in predicate[1]]
    if kind=='match': return list(word)==path
    if kind=='startswith': return list(word)[:len(path)]==path
    if kind=='endswith': return not path or list(word)[-len(path):]==path
    if kind=='contains':
        if not path: return True
        return any(list(word)[i:i+len(path)]==path for i in range(len(word)-len(path)+1))
def allowed(word):
    al=dr=False
    for pred,act in rules:
        if evaluate(pred,word):
            if act: al=True
            else: dr=True
    return al and not dr
import itertools
def run(image,word):
    st=0
    for sym in word:
        if st==4294967295: return False
        st=image['rows'][st][sym]
    return st!=4294967295 and image['accept'][st]
bad=0
